package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import javax.xml.namespace.QName;
import org.apache.commons.jxpath.AbstractFactory;
import org.apache.commons.jxpath.JXPathAbstractFactoryException;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathIntrospector;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.PropertyPointer;
import org.apache.commons.jxpath.util.ValueUtils;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Spy;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class PropertyPointer_createChild_TriageGen0Test {

    @Spy
    private PropertyPointer propertyPointerSpy;

    @Mock
    private JXPathContext mockContext;

    @Mock
    private NodePointer mockReturnedPath;

    @Before
    public void setUp() {
        // Since PropertyPointer is abstract and has a protected constructor, 
        // and the method calls clone(), we use a Mockito Spy on a concrete-like implementation 
        // or a mock that handles the internal logic.
        // However, the method calls clone() which returns a PropertyPointer.
        // For testing purposes, we must ensure clone() returns a valid PropertyPointer object.
    }

    /**
     * Test case where name is NOT null.
     * This covers the 'if (name != null)' branch.
     */
    @Test
    public void testCreateChild_WithValidName() {
        // Arrange
        QName name = new QName("http://test", "testProperty");
        int index = 5;

        // We need a concrete implementation to test the logic. 
        // Since PropertyPointer is abstract, we mock it but we must handle the clone() call.
        PropertyPointer spyPointer = mock(PropertyPointer.class);
        PropertyPointer clonedPointer = mock(PropertyPointer.class);

        when(spyPointer.clone()).thenReturn(clonedPointer);
        when(clonedPointer.createPath(mockContext)).thenReturn(mockReturnedPath);

        // Act
        NodePointer result = spyPointer.createChild(mockContext, name, index);

        // Assert
        verify(clonedPointer).setPropertyName(name.toString());
        verify(clonedPointer).setIndex(index);
        verify(clonedPointer).createPath(mockContext);
        assertEquals(mockReturnedPath, result);
    }

    /**
     * Test case where name IS null.
     * This covers the 'if (name != null)' else logic (skipping setPropertyName).
     */
    @Test
    public void testCreateChild_WithNullName() {
        // Arrange
        QName name = null;
        int index = 10;

        PropertyPointer spyPointer = mock(PropertyPointer.class);
        PropertyPointer clonedPointer = mock(PropertyPointer.class);

        when(spyPointer.clone()).thenReturn(clonedPointer);
        when(clonedPointer.createPath(mockContext)).thenReturn(mockReturnedPath);

        // Act
        NodePointer result = spyPointer.createChild(mockContext, name, index);

        // Assert
        // Verify setPropertyName was NEVER called because name was null
        verify(clonedPointer, org.mockito.Mockito.never()).setPropertyName(org.mockito.ArgumentMatchers.anyString());
        verify(clonedPointer).setIndex(index);
        verify(clonedPointer).createPath(mockContext);
        assertEquals(mockReturnedPath, result);
    }

    /**
     * Test case to ensure index is applied correctly even if name is null.
     */
    @Test
    public void testCreateChild_IndexApplication() {
        // Arrange
        QName name = null;
        int index = -1;

        PropertyPointer spyPointer = mock(PropertyPointer.class);
        PropertyPointer clonedPointer = mock(PropertyPointer.class);

        when(spyPointer.clone()).thenReturn(clonedPointer);
        when(clonedPointer.createPath(mockContext)).thenReturn(mockReturnedPath);

        // Act
        spyPointer.createChild(mockContext, name, index);

        // Assert
        verify(clonedPointer).setIndex(index);
    }
}

// Mocking helper for the abstract class context in a single file test environment
@org.apache.commons.jxpath.ri.model.beans.PropertyPointer
interface PropertyPointerMock extends PropertyPointer {}
